import{_ as n,C as o,o as s,c as e,j as i,E as l,a as r,a2 as d}from"./chunks/framework.C21TwvGF.js";const x=JSON.parse('{"title":"3-hafta (Mentor)","description":"","frontmatter":{"title":"3-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"10-sinf (UX/UI)","link":"/mentor/10-sinf-uxui/"},"n":3,"bob":"III-bob · UI dizayn elementlari va vizual ierarxiya","lessons":[{"g":7,"title":"7-dars: Ranglar psixologiyasi va tipografiya","lead":"Ranglar psixologiyasi va tipografiya","link":"/mentor/10-sinf-uxui/hafta-03/dars-1","slide":"/slaydlar/10-sinf-uxui/hafta-03/dars-1.html","test":"/slaydlar/10-sinf-uxui/hafta-03/dars-1-test.html"},{"g":8,"title":"8-dars: Grid tizimlari va kompozitsiya","lead":"Grid tizimlari va kompozitsiya","link":"/mentor/10-sinf-uxui/hafta-03/dars-2","slide":"/slaydlar/10-sinf-uxui/hafta-03/dars-2.html","test":"/slaydlar/10-sinf-uxui/hafta-03/dars-2-test.html"},{"g":9,"title":"9-dars: Ikonka, tugma va navigatsiya elementlarini dizayni (UI Kit)","lead":"Ikonka, tugma va navigatsiya elementlarini dizayni (UI Kit)","link":"/mentor/10-sinf-uxui/hafta-03/dars-3","slide":"/slaydlar/10-sinf-uxui/hafta-03/dars-3.html","test":"/slaydlar/10-sinf-uxui/hafta-03/dars-3-test.html"}],"test":"/slaydlar/10-sinf-uxui/hafta-03/hafta-test.html"}},"headers":[],"relativePath":"mentor/10-sinf-uxui/hafta-03/index.md","filePath":"mentor/10-sinf-uxui/hafta-03/index.md"}'),h={name:"mentor/10-sinf-uxui/hafta-03/index.md"},u={class:"blk"},m={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},g={class:"blk"},y={id:"baholash-mezoni",tabindex:"-1"};function k(b,a,c,v,f,p){const t=o("Icon");return s(),e("div",null,[i("div",u,[i("h2",m,[l(t,{name:"house"}),a[0]||(a[0]=r(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=d('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h2 id="_7-dars-ranglar-psixologiyasi-va-tipografiya" tabindex="-1">7-dars: Ranglar psixologiyasi va tipografiya <a class="header-anchor" href="#_7-dars-ranglar-psixologiyasi-va-tipografiya" aria-label="Permalink to &quot;7-dars: Ranglar psixologiyasi va tipografiya&quot;">​</a></h2><ol><li>O&#39;zingiz tanlagan bitta veb-sayt yoki mobil ilova loyihasi uchun <strong>60-30-10 qoidasi</strong> bo&#39;yicha ranglar palitrasini tuzing: <ul><li>60% — Asosiy fon rangi;</li><li>30% — Ikkilamchi strukturaviy rang (kartochkalar, matn, menyu);</li><li>10% — Aksent rang (harakatga chaqiruvchi tugmalar va diqqatni tortuvchi elementlar).</li></ul></li><li>Tanlagan aksent rang va uning ustidagi matn kontrasti <strong>WCAG AA (kamida 4.5 : 1)</strong> talabiga to&#39;liq javob berishini kontrast tekshiruvchi vosita (masalan, WebAIM Contrast Checker) orqali tekshirib, natijasini yozing.</li><li>Shrift o&#39;lchamlari uchun <strong>Modular Scale (1.250 — Major Third)</strong> asosida o&#39;lchamlar ierarxiyasini tuzing: Body (16px), Subtitle (20px), H3 (25px), H2 (31px), H1 (39px).</li></ol><hr><h2 id="_8-dars-grid-tizimlari-va-kompozitsiya" tabindex="-1">8-dars: Grid tizimlari va kompozitsiya <a class="header-anchor" href="#_8-dars-grid-tizimlari-va-kompozitsiya" aria-label="Permalink to &quot;8-dars: Grid tizimlari va kompozitsiya&quot;">​</a></h2><ol><li>Desktop ekran (12 ustunli grid) uchun quyidagi sahifa strukturasini loyihalang va har bir blok necha ustun egallashini yozing: <ul><li>Chap tomondagi doimiy navigatsiya paneli (sidebar);</li><li>O&#39;rtadagi asosiy kontent va maqolalar bloki;</li><li>O&#39;ng tomondagi tezkor bildirishnomalar va tavsiyalar bloki.</li></ul></li><li>Sanoat standarti bo&#39;lgan <strong>8pt spacing (panjara) tizimi</strong>dan foydalanib, bitta mahsulot kartochkasi ichidagi barcha masofalarni (ichki padding, rasm va sarlavha orasi, matn va tugma orasi) faqat 8 ga karrali (4, 8, 16, 24, 32px) o&#39;lchamlarda belgilang.</li><li>12 ustunli desktop grididan 4 ustunli mobil gridga o&#39;tganda kartochkalar qanday qayta joylashishini 2-3 jumlada tushuntiring.</li></ol><hr><h2 id="_9-dars-ikonka-tugma-va-navigatsiya-elementlarini-dizayni-ui-kit" tabindex="-1">9-dars: Ikonka, tugma va navigatsiya elementlarini dizayni (UI Kit) <a class="header-anchor" href="#_9-dars-ikonka-tugma-va-navigatsiya-elementlarini-dizayni-ui-kit" aria-label="Permalink to &quot;9-dars: Ikonka, tugma va navigatsiya elementlarini dizayni (UI Kit)&quot;">​</a></h2><ol><li>Figma dasturida <strong>Auto Layout (<code>Shift + A</code>)</strong> yordamida bitta Primary va bitta Secondary tugma yarating: <ul><li>Matn: Inter / Roboto, 16px, Semibold;</li><li>Ichki padding: Horizontal — 24px, Vertical — 12px;</li><li>Burchak radiusi: 8px;</li><li>Minimal balandlik kamida 44px bo&#39;lishini ta&#39;minlang.</li></ul></li><li>Yaratingan Primary tugma uchun 5 ta holatni (Enabled, Hover, Focus, Active, Disabled) loyihalashtiring va ularni bitta Component Set (Variants) sifatida birlashtiring.</li><li>Yangi mobil ilova uchun 4 ta universal navigatsiya piktogrammasini (Bosh sahifa, Qidiruv, Xabarlar, Profil) 24×24px freymlar ichida tartibga keltiring.</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-jami-100-ball" tabindex="-1">Baholash mezonlari (Jami 100 ball) <a class="header-anchor" href="#baholash-mezonlari-jami-100-ball" aria-label="Permalink to &quot;Baholash mezonlari (Jami 100 ball)&quot;">​</a></h3><ul><li><strong>7-dars vazifasi (30 ball):</strong> 60-30-10 qoidasi to&#39;g&#39;ri qo&#39;llangani, kontrast koeffitsienti 4.5:1 dan yuqori ekani va modular scale tipografik pog&#39;onalari to&#39;g&#39;ri hisoblangani.</li><li><strong>8-dars vazifasi (35 ball):</strong> 12 ustunli gridda bloklar taqsimoti matematik to&#39;g&#39;ri yig&#39;ilgani ($Sidebar + Content + Aside = 12$), 8pt spacing qat&#39;iy saqlangani va responsiv mantiq tushunilgani.</li><li><strong>9-dars vazifasi (35 ball):</strong> Figma Auto Layout to&#39;g&#39;ri ishlashi, 44px me&#39;yoriga rioya qilingani, tugmaning barcha 5 ta holati xatosiz ko&#39;rsatilgani va universal ikonalar tanlangani.</li></ul><h3 id="eslatma" tabindex="-1">Eslatma <a class="header-anchor" href="#eslatma" aria-label="Permalink to &quot;Eslatma&quot;">​</a></h3><ul><li>O&#39;quvchilar tugma ichiga matn yozayotganda noaniq jumlalardan qochishi va Auto Layout parametrlarida qat&#39;iy 8pt qoidasiga (padding 24x12px) amal qilishini tekshiring.</li></ul>',16))]),i("div",g,[i("h2",y,[l(t,{name:"list-checks"}),a[3]||(a[3]=r(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=d('<p><strong>Mavzular:</strong></p><ol><li>Ranglar psixologiyasi va tipografiya: 60-30-10 qoidasi, WCAG 4.5:1 kontrasti, tipografik ierarxiya, Modular scale</li><li>Grid tizimlari va kompozitsiya: 6 ta grid turi, 12 ustunli responsiv grid (Columns, Gutter, Margin), 8pt spacing tizimi</li><li>Ikonka, tugma va navigatsiya elementlarini dizayni: Primary/Secondary/Ghost/FAB tugmalar, 5 ta holat, 44px qoidasi, UI Kit</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Ranglar &amp; Tipografiya</strong></td><td>60-30-10 qoidasi, aksent va fon kontrasti (kamida 4.5:1 tekshiruvi), modular scale bo&#39;yicha shrift o&#39;lchamlari ierarxiyasi</td><td>30 ball</td></tr><tr><td><strong>Grid &amp; Kompozitsiya</strong></td><td>12 ustunli desktop gridda ustunlar hisobi (jami 12 ustun), 8pt tizimi bo&#39;yicha oraliqlar (4, 8, 16, 24, 32px), responsiv o&#39;tish</td><td>35 ball</td></tr><tr><td><strong>Tugmalar &amp; UI Kit</strong></td><td>Figma Auto Layout (<code>Shift + A</code>), 44px minimal o&#39;lcham, 5 ta tugma holati (Variants), universal navigatsiya ikonkalari</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Rang &amp; Shrift (30)</th><th>Grid &amp; 8pt (35)</th><th>Tugma &amp; UI Kit (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar ko&#39;pincha tugma o&#39;lchamini belgilashda matnning fonidagi paddingni unchalik hisobga olishmaydi yoki qat&#39;iy 8pt qoidasidan chetga chiqib, 13px, 17px kabi tasodifiy masofalarni qo&#39;yishadi. Ularga har doim 8 ga karrali sonlardan foydalanish intizomini singdirish lozim.</li><li><strong>Accessibility talabi:</strong> Ko&#39;pchilik o&#39;quvchilar tugmaning Focus holatini ikkinchi darajali deb hisoblashadi. Imkoniyati cheklangan foydalanuvchilar va klaviatura orqali harakatlanishda bu holat qanchalik muhimligini amalda ko&#39;rsatish zarur.</li></ul>',11))])])}const z=n(h,[["render",k]]);export{x as __pageData,z as default};
